"""R1 static runtime audit; tests may use pytest, minisql itself may not.

Python >=3.10 supplies sys.stdlib_module_names. On the available 3.9 host,
use the interpreter's configured stdlib/platstdlib and lib-dynload directories
plus builtin names, never sys.path or site-packages. The fallback is not a
claim that Python 3.9 meets the product's >=3.11 runtime requirement.
"""

import ast
import importlib.machinery
from pathlib import Path
import pkgutil
import sys
import sysconfig

import pytest


ROOT = Path(__file__).resolve().parents[1]
PACKAGE = ROOT / "minisql"
FORBIDDEN = {"sqlite3", "_sqlite3", "sqlparse", "sqlglot", "duckdb", "sqlalchemy",
             "pglast", "moz_sql_parser", "sql_metadata", "pyparsing", "lark"}


def stdlib_names():
    if hasattr(sys, "stdlib_module_names"):
        return set(sys.stdlib_module_names)
    names = set(sys.builtin_module_names)
    directories = set()
    for key in ("stdlib", "platstdlib"):
        directory = Path(sysconfig.get_path(key))
        directories.add(directory)
        directories.add(directory / "lib-dynload")
    for directory in directories:
        if directory.is_dir():
            names.update(module.name for module in pkgutil.iter_modules([str(directory)]))
    return names - {"site-packages", "dist-packages"}


def import_targets(tree):
    """Yield static imports, including literal dynamic-import calls.

    Unresolvable dynamic imports fail the audit rather than silently passing.
    Relative imports are checked against the on-disk package separately.
    """
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                yield alias.name, 0, node.lineno
        elif isinstance(node, ast.ImportFrom):
            yield node.module or "", node.level, node.lineno
        elif isinstance(node, ast.Call):
            function = node.func
            dynamic = (isinstance(function, ast.Name) and function.id == "__import__") or (
                isinstance(function, ast.Attribute) and function.attr == "import_module")
            if dynamic:
                assert node.args and isinstance(node.args[0], ast.Constant) and isinstance(
                    node.args[0].value, str), "nonliteral dynamic import cannot be statically audited"
                name = node.args[0].value
                yield name.lstrip("."), len(name) - len(name.lstrip(".")), node.lineno


def local_module_exists(parts):
    path = ROOT.joinpath(*parts)
    return path.with_suffix(".py").is_file() or (path / "__init__.py").is_file()


def audit_source(source, path, allowed):
    tree = ast.parse(source, filename=str(path))
    compile(tree, str(path), "exec")
    for name, level, line in import_targets(tree):
        first = name.split(".")[0]
        assert first not in FORBIDDEN, "{}:{} forbidden SQL/parser import {}".format(path, line, name)
        if level:
            relative_parent = path.relative_to(ROOT).parent.parts
            assert level <= len(relative_parent), "relative import escapes runtime package"
            base = relative_parent[:len(relative_parent) - level + 1]
            parts = base + tuple(name.split(".")) if name else base
            assert local_module_exists(parts), "{}:{} missing local module {}".format(path, line, name)
        elif first == "minisql":
            assert local_module_exists(tuple(name.split("."))), "missing package module " + name
        else:
            assert first in allowed, "{}:{} non-stdlib import {}".format(path, line, name)
    return tree


def test_r1_flat_package_layout_and_handwritten_engine_layers():
    assert PACKAGE.is_dir()
    assert not (ROOT / "src" / "minisql").exists()
    for name in ("__init__", "__main__", "lexer", "ast", "parser", "semantic", "executor"):
        assert (PACKAGE / (name + ".py")).is_file(), "missing runtime layer " + name


def test_runtime_files_compile_and_only_import_stdlib_or_own_package():
    allowed = stdlib_names()
    paths = sorted(PACKAGE.rglob("*.py"))
    assert paths and PACKAGE / "__init__.py" in paths
    for path in paths:
        source = path.read_text(encoding="utf-8")
        audit_source(source, path, allowed)
        # sqlite3 is expressly prohibited anywhere in the runtime package.
        assert "sqlite3" not in source.lower(), "sqlite3 reference in " + str(path)


def test_stdlib_inventory_is_not_site_packages_and_covers_runtime_basics():
    allowed = stdlib_names()
    assert {"ast", "csv", "dataclasses", "os", "sys", "math", "argparse", "pathlib", "re"} <= allowed
    assert not ({"pytest", "sqlparse", "sqlglot", "duckdb", "sqlalchemy"} & allowed)
    for name in ("csv", "ast", "dataclasses"):
        spec = importlib.machinery.PathFinder.find_spec(name, [sysconfig.get_path("stdlib")])
        assert spec is not None


@pytest.mark.parametrize("source", [
    "import sqlite3", "from sqlite3 import connect", "import sqlparse", "import duckdb",
    "from sqlalchemy import text", "import pytest", "import not_a_stdlib_module",
    "__import__('sqlite3')", "importlib.import_module('sqlglot')",
    "__import__(variable)", "importlib.import_module(variable)",
])
def test_audit_rejects_forbidden_external_and_unresolvable_imports(source):
    with pytest.raises(AssertionError):
        audit_source(source, PACKAGE / "__init__.py", stdlib_names())


@pytest.mark.parametrize("source", ["import csv, math", "from dataclasses import dataclass",
                                         "from .errors import MiniSQLError", "from minisql.model import Result"])
def test_audit_accepts_stdlib_and_existing_own_modules(source):
    audit_source(source, PACKAGE / "__init__.py", stdlib_names())

